using Godot;
using Glyphwake.Core;

namespace Glyphwake.Player;

/// Holds the airborne pose: the head upright, and the upper back un-hunched, while a jump clip
/// plays.
///
/// The jump clips tuck the spine -- the coil on the way up, a much deeper tuck on the way down,
/// held frozen once the scaled clip runs out -- and the authored neck counter is too shallow to
/// hold the head level, so the head dips with the spine. With the head held upright instead,
/// the tuck reads as a hunch: the shoulder girdle rides the curled spine up to and past the
/// head. The clips are regenerated by tools/build_stickman.gd, which is currently unparseable
/// (tracked in CURRENT_TODO), so this corrects the pose at runtime instead.
///
/// The corrections are applied in _Process rather than in the modifier pass, because a
/// SetBoneGlobalPose issued from inside the SkeletonModifier3D pass is discarded for bones the
/// clips animate -- the skeleton re-derives those from the animation -- and the jump clips
/// animate the head and the spine. Late process priority is what guarantees this runs after
/// the AnimationPlayer has written the frame, the same place the swim's arm clamp runs.
///
/// The head takes every tilt from vertical out and keeps the facing it already has, so the
/// body coils and the head does not -- the read the baked body lean asks for. The upper back
/// (Spine1, Spine2 -- the bones whose curl carries the shoulder girdle) takes
/// <see cref="UpperBackDamp"/> of its curl away, in skeleton space: the pose basis excludes the
/// visual's own lean, so the damp takes the clip's curl and leaves the designed direction tilt
/// alone. Positions are left where the clip put them; only the head's and spine's orientations
/// are corrected, and the lower back keeps its coil so the jump still reads as a crouch and
/// extend. Both corrections run while the locomotion state is a jump clip, which covers the
/// standing jump, the running jump and the ledge fall (the bare clip), and keep running under
/// an air-step cast: the cast's one-shot only overrides the tracks its clip animates, so the
/// pose stays with the jump clip playing underneath. They also hold for
/// <see cref="ReleaseTime"/> after the state leaves the jump clip -- the travel crossfade
/// blends through the clip's tucked end pose, and corrections that stop on the landing frame
/// let that tuck back through in one frame -- then stand down. The handover pop is the landed
/// pose's own few-degree tilt, not the tuck.
public partial class AirbornePose : SkeletonModifier3D
{
	[Export] public float ReleaseTime = 0.15f;

	/// The share of the upper back's curl taken away while a jump clip plays. 1 would stand the
	/// spine dead straight; 0.8 leaves a fifth of the tuck, which reads as a lean rather than a
	/// hunch under the upright head. The lower back is untouched, so the coil still reads.
	[Export] public float UpperBackDamp = 0.8f;

	private Skeleton3D _skeleton;
	private PlayerController _player;
	private int _headBone = -1;
	private int[] _upperBack = System.Array.Empty<int>();
	private float _release;

	public override void _Ready()
	{
		_skeleton = GetParent() as Skeleton3D;
		Node n = GetParent();
		while (n != null && n is not PlayerController)
			n = n.GetParent();
		_player = n as PlayerController;

		if (_skeleton == null)
			return;
		_headBone = _skeleton.FindBone(PlayerRig.HeadBoneName);
		_upperBack = new[]
		{
			_skeleton.FindBone(PlayerRig.Spine1BoneName),
			_skeleton.FindBone(PlayerRig.Spine2BoneName),
		};
		ProcessPriority = 100;
	}

	public override void _Process(double delta)
	{
		if (_skeleton == null || _player == null || _headBone < 0)
			return;

		if (AnimationIds.IsJumpClip(_player.AnimationState))
		{
			_release = ReleaseTime;
			ApplyPose();
			return;
		}

		if (_release <= 0f)
			return;
		_release -= (float)delta;
		ApplyPose();
	}

	private void ApplyPose()
	{
		DampUpperBack();
		LevelHead(_headBone);
	}

	// Takes UpperBackDamp of the curl away from each upper-back bone, about the bone's own
	// right axis. Spine2 is a child of Spine1, so the second counter reads the pose the first
	// one already corrected and the two compose -- the whole girdle comes back down together.
	// The tilt is measured in skeleton space, so the visual's own lean never reaches it.
	private void DampUpperBack()
	{
		foreach (int bone in _upperBack)
		{
			if (bone < 0)
				continue;
			Transform3D pose = _skeleton.GetBoneGlobalPose(bone);
			Basis basis = pose.Basis.Orthonormalized();
			Vector3 up = basis.Y;
			Vector3 right = basis.X;
			float sin = up.Cross(Vector3.Up).Dot(right);
			float cos = up.Dot(Vector3.Up);
			float angle = Mathf.Atan2(sin, cos);
			Quaternion corrected = new Quaternion(right, angle * UpperBackDamp)
				* basis.GetRotationQuaternion();
			_skeleton.SetBoneGlobalPose(bone, new Transform3D(new Basis(corrected), pose.Origin));
		}
	}

	private void LevelHead(int headBone)
	{
		Transform3D pose = _skeleton.GetBoneGlobalPose(headBone);
		Basis skeletonBasis = _skeleton.GlobalTransform.Basis.Orthonormalized();
		Basis headWorld = (skeletonBasis * pose.Basis).Orthonormalized();
		float yaw = headWorld.GetRotationQuaternion().GetEuler().Y;
		Basis leveled = skeletonBasis.Inverse() * new Basis(Vector3.Up, yaw);
		_skeleton.SetBoneGlobalPose(headBone, new Transform3D(leveled, pose.Origin));
	}
}
